public class PhotoTest {
    private final Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();private TestIdle idle;private final List<Uri> media=new ArrayList<>();
    @Before public void before(){idle=TestIdle.register();}
    @After public void after(){idle.close();for(Uri uri:media)context.getContentResolver().delete(uri,null,null);}
    static byte[] picture() throws Exception {Bitmap b=Bitmap.createBitmap(1200,600,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(Color.WHITE);Paint p=new Paint();p.setColor(0xffD94343);c.drawRect(0,0,600,600,p);p.setColor(0xff2668C8);c.drawRect(600,0,1200,600,p);p.setColor(Color.WHITE);p.setTextSize(72);c.drawText("NotePocket photo",140,330,p);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();return out.toByteArray();}
    private Uri mediaPicture(String name) throws Exception {ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,name);v.put(MediaStore.Images.Media.MIME_TYPE,"image/png");Uri uri=context.getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);assertNotNull(uri);media.add(uri);try(OutputStream out=context.getContentResolver().openOutputStream(uri)){out.write(picture());}return uri;}
    private long note(String title,String body){try(Store store=new Store(context)){return store.save(-1,title,body,"","ทั่วไป");}}
    @Test public void pickerInsertsPhotoAtCursorAndUndoKeepsOriginalFile() throws Exception {
        String original="ข้อความก่อนรูป\nข้อความหลังรูป";long id=note("Photo picker insert test",original);Uri uri=mediaPicture("inline-picked-photo.png");
        try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){
            onView(withText("Photo picker insert test")).perform(click());scenario.onActivity(a->find(a.getWindow().getDecorView()).setSelection(original.indexOf("ข้อความหลัง")));
            IntentFilter filter=new IntentFilter(Intent.ACTION_OPEN_DOCUMENT);filter.addCategory(Intent.CATEGORY_OPENABLE);filter.addDataType("image/*");Instrumentation.ActivityMonitor monitor=InstrumentationRegistry.getInstrumentation().addMonitor(filter,new Instrumentation.ActivityResult(Activity.RESULT_OK,new Intent().setData(uri)),true);
            try{onView(withContentDescription("แทรกรูปภาพตรงเคอร์เซอร์")).perform(scrollTo(),click());onView(withText("เลือกรูปจากเครื่อง")).inRoot(androidx.test.espresso.matcher.RootMatchers.isDialog()).perform(click());awaitPhotos(scenario,1);assertTrue(monitor.getHits()>0);}finally{InstrumentationRegistry.getInstrumentation().removeMonitor(monitor);}
            AtomicReference<String> image=new AtomicReference<>();scenario.onActivity(a->{InlineNoteEditText b=find(a.getWindow().getDecorView());List<InlineImages.Block> blocks=InlineImages.find(b.getText().toString());assertEquals(1,blocks.size());image.set(blocks.get(0).id);assertTrue(b.getText().toString().startsWith("ข้อความก่อนรูป\n"));assertTrue(b.getText().toString().endsWith("ข้อความหลังรูป"));int first=b.getLayout().getLineForOffset(0),after=b.getLayout().getLineForOffset(b.getText().toString().indexOf("ข้อความหลัง"));int distance=b.getLayout().getLineTop(after)-b.getLayout().getLineTop(first);int expected=b.getLayout().getLineBottom(first)-b.getLayout().getLineTop(first)+b.spans()[0].height();assertEquals(expected,distance,b.dp(3));});screenshot("23-photo-between-note-paragraphs");onView(withText("inline-picked-photo.png")).check(androidx.test.espresso.assertion.ViewAssertions.doesNotExist());onView(withContentDescription("ย้อนกลับข้อความ")).perform(scrollTo(),click());scenario.onActivity(a->assertEquals(original,find(a.getWindow().getDecorView()).getText().toString()));onView(withContentDescription("กลับจากโน้ต")).perform(click());try(Store store=new Store(context)){assertEquals(original,store.note(id).getAsString("body"));assertTrue(InlineImages.file(context,image.get()).isFile());assertTrue(store.attachments(id).isEmpty());}
        }
    }
    @Test public void clipboardAndKeyboardContentPasteTwoRealImages() throws Exception {
        note("Photo clipboard keyboard test","จุดเริ่มต้น\n");Uri clipboard=mediaPicture("clipboard-photo.png"),keyboard=mediaPicture("keyboard-photo.png");
        try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){
            onView(withText("Photo clipboard keyboard test")).perform(click());scenario.onActivity(a->{InlineNoteEditText b=find(a.getWindow().getDecorView());b.requestFocus();b.setSelection(b.length());((android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newUri(a.getContentResolver(),"photo",clipboard));assertTrue(b.onTextContextMenuItem(android.R.id.paste));});awaitPhotos(scenario,1);
            scenario.onActivity(a->{InlineNoteEditText b=find(a.getWindow().getDecorView());b.requestFocus();b.setSelection(b.length());EditorInfo info=new EditorInfo();InputConnection input=b.onCreateInputConnection(info);assertTrue(Arrays.asList(EditorInfoCompat.getContentMimeTypes(info)).contains("image/*"));assertTrue(input.commitContent(new InputContentInfo(keyboard,new ClipDescription("photo",new String[]{"image/png"}),null),0,null));});awaitPhotos(scenario,2);
            scenario.onActivity(a->{InlineNoteEditText b=find(a.getWindow().getDecorView());assertTrue(b.getText().toString().startsWith("จุดเริ่มต้น\n"));assertEquals(2,InlineImages.ids(b.getText().toString()).size());((android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).clearPrimaryClip();});dismissClipboard();onView(withContentDescription("กลับจากโน้ต")).perform(click());
        }
    }
    @Test public void existingAttachmentBecomesInlineWithoutDuplicateAndOpensZoomViewer() throws Exception {
        String before="ก่อนภาพ\nหลังภาพ";long n=note("Photo existing attachment test",before);ContentValues doc;try(Store store=new Store(context)){doc=InlineImages.importImage(context,store,new ByteArrayInputStream(picture()),"existing-note-photo.png");store.attach(n,doc.getAsString("id"));}String id=doc.getAsString("id");long bytes=InlineImages.file(context,id).length();
        try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){
            onView(withText("Photo existing attachment test")).perform(click());scenario.onActivity(a->find(a.getWindow().getDecorView()).setSelection(before.indexOf("หลังภาพ")));onView(withText("แทรกในโน้ต")).perform(scrollTo(),click());awaitPhotos(scenario,1);scenario.onActivity(a->assertEquals(Collections.singleton(id),InlineImages.ids(find(a.getWindow().getDecorView()).getText().toString())));onView(withText("existing-note-photo.png")).check(androidx.test.espresso.assertion.ViewAssertions.doesNotExist());tapPhoto(scenario);onView(withText("เปิดรูป / ซูม")).inRoot(androidx.test.espresso.matcher.RootMatchers.isDialog()).perform(click());awaitViewer();onView(withContentDescription("รูปภาพในโน้ต")).perform(doubleClick());screenshot("24-photo-fullscreen-zoom");onView(withContentDescription("กลับจากรูปภาพ")).perform(click());awaitPhotos(scenario,1);onView(withContentDescription("กลับจากโน้ต")).perform(click());
        }
        try(Store store=new Store(context)){assertEquals(1,store.query("SELECT id FROM docs WHERE id=?",id).size());assertEquals(bytes,InlineImages.file(context,id).length());assertEquals(id,store.attachments(n).get(0).getAsString("id"));}
    }
    @Test public void backupRemapsVariableLengthPhotoIdsAndFormattingWithoutChangingOriginal() throws Exception {
        Space c=new Space(context);try(Store store=new Store(c,"photos.db")){
            String old="old-photo";try(OutputStream out=new FileOutputStream(InlineImages.file(c,old))){out.write(picture());}ContentValues doc=new ContentValues();doc.put("id",old);doc.put("name","original.png");doc.put("mime","image/png");doc.put("size",InlineImages.file(c,old).length());store.getWritableDatabase().insertOrThrow("docs",null,doc);String body="ก่อน\n"+InlineImages.marker(old)+"\nหลังรูป";SpannableString rich=new SpannableString(body);rich.setSpan(new ForegroundColorSpan(Color.RED),body.indexOf("หลังรูป"),body.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);long original=store.save(-1,"photo backup",body,NoteFormat.encode(rich),"ทั่วไป");assertEquals(old,store.attachments(original).get(0).getAsString("id"));ByteArrayOutputStream archive=new ByteArrayOutputStream();Backup.write(c,store,archive);Backup.restore(c,store,new ByteArrayInputStream(archive.toByteArray()));ContentValues copy=store.query("SELECT * FROM notes WHERE id<>?",""+original).get(0);String id=InlineImages.find(copy.getAsString("body")).get(0).id;assertNotEquals(old,id);assertTrue(InlineImages.file(c,id).isFile());assertEquals(id,store.attachments(copy.getAsLong("id")).get(0).getAsString("id"));Spanned decoded=NoteFormat.decode(copy.getAsString("rich"),copy.getAsString("body"));ForegroundColorSpan span=decoded.getSpans(0,decoded.length(),ForegroundColorSpan.class)[0];assertEquals("หลังรูป",decoded.subSequence(decoded.getSpanStart(span),decoded.getSpanEnd(span)).toString());assertEquals(body,store.note(original).getAsString("body"));store.eraseDoc(old);assertTrue(InlineImages.ids(store.note(original).getAsString("body")).isEmpty());assertEquals(Collections.singleton(id),InlineImages.ids(store.note(copy.getAsLong("id")).getAsString("body")));
            String literal="```text\n"+InlineImages.marker(id)+"\n```";assertTrue(InlineImages.find(literal).isEmpty());
        }finally{Backup.deleteTree(c.root);}
    }
    @Test public void exifRotationAndInvalidFilesPreserveStoredOriginals() throws Exception {
        Space c=new Space(context);try(Store store=new Store(c,"photos.db")){
            File camera=new File(c.getCacheDir(),"camera.jpg");Bitmap source=Bitmap.createBitmap(100,60,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(source);canvas.drawColor(Color.RED);Paint paint=new Paint();paint.setColor(Color.BLUE);canvas.drawRect(50,0,100,60,paint);try(OutputStream out=new FileOutputStream(camera)){source.compress(Bitmap.CompressFormat.JPEG,95,out);}source.recycle();ExifInterface exif=new ExifInterface(camera);exif.setAttribute(ExifInterface.TAG_ORIENTATION,"6");exif.saveAttributes();ContentValues row;try(InputStream in=new FileInputStream(camera)){row=InlineImages.importImage(c,store,in,"camera.jpg");}File original=InlineImages.file(c,row.getAsString("id"));byte[] unchanged=java.nio.file.Files.readAllBytes(original.toPath());Bitmap image=InlineImages.decode(original,1000,1500000);assertEquals(60,image.getWidth());assertEquals(100,image.getHeight());assertTrue(Color.red(image.getPixel(30,10))>Color.blue(image.getPixel(30,10)));image.recycle();assertArrayEquals(unchanged,java.nio.file.Files.readAllBytes(original.toPath()));int count=store.query("SELECT id FROM docs").size();try{InlineImages.importImage(c,store,new ByteArrayInputStream(new byte[]{1,2,3}),"broken.jpg");fail();}catch(IOException expected){}assertEquals(count,store.query("SELECT id FROM docs").size());assertTrue(original.isFile());
        }finally{Backup.deleteTree(c.root);}
    }
    private void awaitPhotos(ActivityScenario<MainActivity> scenario,int count)throws Exception{long until=System.currentTimeMillis()+25000;while(System.currentTimeMillis()<until){AtomicBoolean ready=new AtomicBoolean();scenario.onActivity(a->{InlineNoteEditText b=find(a.getWindow().getDecorView());if(b==null)return;int images=0;boolean ok=b.isIdle();for(InlineDiagramSpan s:b.spans())if(s.photo){images++;ok&=b.bitmap(s.key)!=null;}ready.set(ok&&images==count);});if(ready.get())return;Thread.sleep(100);}fail("Inline photos not ready");}
    private void awaitViewer()throws Exception{long until=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<until){AtomicBoolean ready=new AtomicBoolean();InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof PhotoActivity)for(TextView t:texts(a.getWindow().getDecorView()))if(t.getText().toString().startsWith("ใช้สองนิ้วซูม"))ready.set(true);});if(ready.get())return;Thread.sleep(100);}fail("Photo viewer not ready");}
    private static List<TextView> texts(View v){List<TextView> out=new ArrayList<>();if(v instanceof TextView)out.add((TextView)v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)out.addAll(texts(((ViewGroup)v).getChildAt(i)));return out;}
    private void tapPhoto(ActivityScenario<MainActivity> scenario)throws Exception{AtomicReference<float[]> point=new AtomicReference<>();scenario.onActivity(a->{InlineNoteEditText b=find(a.getWindow().getDecorView());for(InlineDiagramSpan s:b.spans())if(s.photo){int line=b.getLayout().getLineForOffset(b.getText().getSpanStart(s));int[] p=new int[2];b.getLocationOnScreen(p);point.set(new float[]{p[0]+b.getWidth()/2f,p[1]+b.getTotalPaddingTop()+(b.getLayout().getLineTop(line)+b.getLayout().getLineBottom(line))/2f});break;}});float[] p=point.get();assertNotNull(p);long now=SystemClock.uptimeMillis();android.app.UiAutomation ui=InstrumentationRegistry.getInstrumentation().getUiAutomation();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,p[0],p[1],0),up=MotionEvent.obtain(now,now+80,MotionEvent.ACTION_UP,p[0],p[1],0);try{ui.injectInputEvent(down,true);ui.injectInputEvent(up,true);}finally{down.recycle();up.recycle();}Thread.sleep(200);}
    private static InlineNoteEditText find(View v){if(v instanceof InlineNoteEditText)return(InlineNoteEditText)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){InlineNoteEditText b=find(((ViewGroup)v).getChildAt(i));if(b!=null)return b;}return null;}
    private void screenshot(String name)throws Exception{Thread.sleep(250);Bitmap b=InstrumentationRegistry.getInstrumentation().getUiAutomation().takeScreenshot();File dir=new File(context.getExternalFilesDir(null),"screenshots");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
    private void dismissClipboard(){android.app.UiAutomation ui=InstrumentationRegistry.getInstrumentation().getUiAutomation();android.accessibilityservice.AccessibilityServiceInfo info=ui.getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS|android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;ui.setServiceInfo(info);for(android.view.accessibility.AccessibilityWindowInfo window:ui.getWindows()){android.view.accessibility.AccessibilityNodeInfo root=window.getRoot();if(root==null)continue;for(android.view.accessibility.AccessibilityNodeInfo close:root.findAccessibilityNodeInfosByViewId("com.android.systemui:id/dismiss_button"))close.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);}}
    private static final class Space extends ContextWrapper {final File root,files,cache;Space(Context c){super(c);root=new File(c.getCacheDir(),"photo-space-"+UUID.randomUUID());files=new File(root,"files");cache=new File(root,"cache");files.mkdirs();cache.mkdirs();}@Override public File getFilesDir(){return files;}@Override public File getCacheDir(){return cache;}@Override public File getDatabasePath(String name){return new File(root,name);}@Override public SQLiteDatabase openOrCreateDatabase(String name,int mode,SQLiteDatabase.CursorFactory f){return openOrCreateDatabase(name,mode,f,null);}@Override public SQLiteDatabase openOrCreateDatabase(String name,int mode,SQLiteDatabase.CursorFactory f,DatabaseErrorHandler handler){return SQLiteDatabase.openDatabase(getDatabasePath(name).getPath(),f,SQLiteDatabase.CREATE_IF_NECESSARY|SQLiteDatabase.ENABLE_WRITE_AHEAD_LOGGING,handler);}}
}
